<?php require_once __DIR__ . '/../includes/auth.php'; require_login(); ?>
<div class="table-shell" id="sow-results" aria-busy="false"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Sow tag</th><th>Mating date</th><th>Expected farrowing</th><th>Days remaining</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($records as $row): $days=(int)(new DateTimeImmutable('today'))->diff(new DateTimeImmutable($row['expected_farrowing_date']))->format('%r%a'); $due=$row['status']==='pregnant' && $days >= 0 && $days <= 7; $overdue=$row['status']==='pregnant' && $days < 0; $statusClass=$overdue?'chip-danger':($due?'chip-warning':($row['status']==='farrowed'?'chip-success':($row['status']==='pregnant'?'chip-blue':'chip-brand'))); ?><tr><td class="fw-bold"><?= e($row['tag_number']) ?></td><td><?= e($row['mating_date']) ?></td><td><?= e($row['expected_farrowing_date']) ?></td><td><?= $row['status']==='pregnant' ? ($days < 0 ? abs($days).' overdue' : $days.' days') : ($row['status']==='farrowed' ? 'Completed' : 'Failed') ?></td><td><span class="chip <?= $statusClass ?>"><?= $overdue?'Overdue':($due?'Due soon':ucfirst($row['status'])) ?></span></td><td class="text-end text-nowrap"><div class="table-actions pig-table-actions"><a class="btn btn-outline-secondary action-edit" href="edit.php?id=<?= (int)$row['sow_record_id'] ?>"><i data-lucide="pencil" aria-hidden="true"></i><span>Edit</span></a></div></td></tr><?php endforeach; ?><?php if(!$records): ?><tr><td colspan="6" class="text-center text-muted py-5">No gestation records match these filters.</td></tr><?php endif; ?></tbody></table></div></div>
